"}, {"acl": "{postgres=X/postgres}", "owner": "postgres", "present": true, "security": "INVOKER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "twuanis_canonical_private.publisher_allowance(uuid,uuid)", "definition": "CREATE OR REPLACE FUNCTION twuanis_canonical_private.publisher_allowance(p_publisher uuid, p_owner uuid)
 RETURNS TABLE(subscription_id uuid, package_id uuid, allowance bigint, unlimited boolean, effective_start timestamp with time zone, effective_end timestamp with time zone, observed_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE v_owner uuid; s record; n integer:=0; v_limit integer; v_at timestamptz;
BEGIN
 v_owner:=twuanis_canonical_private.lock_publisher(p_publisher);
 IF p_owner IS DISTINCT FROM v_owner THEN RAISE EXCEPTION 'publisher/customer mismatch' USING ERRCODE='22023'; END IF;
 -- Observe time after waiting; a transaction-start timestamp may already be stale.
 v_at:=clock_timestamp();
 FOR s IN SELECT u.id,u.package_id,u.current_period_start,u.current_period_end
  FROM public.user_subscriptions u WHERE u.user_id=v_owner AND u.status='active' LIMIT 2
 LOOP
  n:=n+1;
  subscription_id:=s.id; package_id:=s.package_id;
  effective_start:=s.current_period_start; effective_end:=s.current_period_end;
 END LOOP;
 IF n<>1 THEN RAISE EXCEPTION 'one authoritative active subscription required' USING ERRCODE='55000'; END IF;
 IF (effective_start IS NOT NULL AND effective_start>v_at)
  OR (effective_end IS NOT NULL AND effective_end<=v_at)
  OR (effective_start IS NOT NULL AND effective_end IS NOT NULL AND effective_end<=effective_start) THEN
  RAISE EXCEPTION 'subscription not effective' USING ERRCODE='55000';
 END IF;
 PERFORM p.id FROM public.packages p WHERE p.id=package_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'subscription package missing' USING ERRCODE='55000'; END IF;
 SELECT l.listing_limit INTO v_limit FROM public.package_limits l WHERE l.package_id=publisher_allowance.package_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'publication limit missing' USING ERRCODE='55000'; END IF;
 IF v_limit<0 THEN RAISE EXCEPTION 'negative publication limit' USING ERRCODE='22023'; END IF;
 allowance:=v_limit::bigint; unlimited:=v_limit IS NULL; observed_at:=v_at;
 RETURN NEXT;
END $function$
"}, {"acl": "{postgres=X/postgres}", "owner": "postgres", "present": true, "security": "INVOKER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "twuanis_canonical_private.publisher_consumption(uuid,uuid)", "definition": "CREATE OR REPLACE FUNCTION twuanis_canonical_private.publisher_consumption(p_publisher uuid, p_owner uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE v_owner uuid; v_count bigint; v_bad bigint;
BEGIN
 v_owner:=twuanis_canonical_private.lock_publisher(p_publisher);
 IF p_owner IS DISTINCT FROM v_owner THEN RAISE EXCEPTION 'publisher/customer mismatch' USING ERRCODE='22023'; END IF;
 SELECT count(*),count(*) FILTER(WHERE l.owner_id IS DISTINCT FROM v_owner)
 INTO v_count,v_bad FROM public.listings l
 WHERE l.publisher_account_id=p_publisher AND l.listing_status='active';
 IF v_bad<>0 THEN RAISE EXCEPTION 'canonical listing ownership mismatch' USING ERRCODE='55000'; END IF;
 RETURN v_count;
END $function$
"}, {"acl": "{postgres=X/postgres}", "owner": "postgres", "present": true, "security": "INVOKER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "twuanis_canonical_private.capacity_state(bigint,bigint)", "definition": "CREATE OR REPLACE FUNCTION twuanis_canonical_private.capacity_state(p_allowance bigint, p_consumption bigint)
 RETURNS TABLE(allowance bigint, consumption bigint, remaining bigint, over_capacity bigint, adding_one_exceeds boolean, is_over_capacity boolean, unlimited boolean)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF p_consumption IS NULL OR p_consumption<0 OR p_allowance<0 THEN
  RAISE EXCEPTION 'invalid capacity numbers' USING ERRCODE='22023';
 END IF;
 allowance:=p_allowance; consumption:=p_consumption; unlimited:=p_allowance IS NULL;
 remaining:=p_allowance-p_consumption;
 over_capacity:=CASE WHEN unlimited THEN 0 ELSE greatest(p_consumption-p_allowance,0) END;
 adding_one_exceeds:=NOT unlimited AND p_consumption>=p_allowance;
 is_over_capacity:=NOT unlimited AND p_consumption>p_allowance;
 RETURN NEXT;
END $function$
"}, {"acl": "{postgres=X/postgres}", "owner": "postgres", "present": true, "security": "INVOKER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "twuanis_canonical_private.s3_sealed_rule_guard()", "definition": "CREATE OR REPLACE FUNCTION twuanis_canonical_private.s3_sealed_rule_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 PERFORM id FROM public.listing_classification_rule_sets WHERE id=NEW.rule_set_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.classification_seals WHERE rule_set_id=NEW.rule_set_id) THEN
  RAISE EXCEPTION 'classification version sealed' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $function$
"}, {"acl": "{postgres=X/postgres}", "owner": "postgres", "present": true, "security": "INVOKER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "twuanis_canonical_private.s3_seal_classification(uuid)", "definition": "CREATE OR REPLACE FUNCTION twuanis_canonical_private.s3_seal_classification(p_set uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
