"}, {"acl": "{postgres=X/postgres,service_role=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "public.create_trusted_canonical_listing(uuid,jsonb,jsonb)", "definition": "CREATE OR REPLACE FUNCTION public.create_trusted_canonical_listing(p_request uuid, p_input jsonb, p_source jsonb DEFAULT NULL::jsonb)
