"}, {"acl": "{postgres=X/postgres,service_role=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog"], "signature": "public.create_csv_canonical_listing(uuid,jsonb,jsonb)", "definition": "CREATE OR REPLACE FUNCTION public.create_csv_canonical_listing(p_request uuid, p_input jsonb, p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE existing_id uuid; result jsonb; actual_receipt uuid;
BEGIN
 IF p_source IS NULL THEN RAISE EXCEPTION 'genuine CSV source observation required' USING ERRCODE='22023'; END IF;
 -- Same capacity/source order as the closed creation boundary. Its locks reenter.
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 PERFORM pg_advisory_xact_lock(3103,hashtext(jsonb_build_array(p_source->>'source_name',p_source->>'source_listing_id')::text));
 SELECT id INTO existing_id FROM public.listings WHERE source_name=p_source->>'source_name' AND source_listing_id=p_source->>'source_listing_id';
 IF existing_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM twuanis_canonical_private.csv_initial_publication WHERE listing_id=existing_id
 ) THEN RAISE EXCEPTION 'existing non-CSV creation cannot acquire CSV eligibility' USING ERRCODE='42501'; END IF;
 result:=public.create_trusted_canonical_listing(p_request,p_input,p_source);
 SELECT r.id INTO STRICT actual_receipt FROM public.canonical_operation_receipts r
 JOIN public.listing_lifecycle_events e ON e.operation_id=r.id AND e.listing_id=r.listing_id
 WHERE r.listing_id=(result->>'listing_id')::uuid AND r.operation_type='create_trusted'
 AND r.authority_kind='trusted' AND r.authority_identity='service_role' AND e.event_type='create';
 -- A replay of unrelated generic creation cannot enroll it through request ID.
 IF existing_id IS NULL AND (result->>'replayed')::boolean THEN
  IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.csv_initial_publication WHERE creation_receipt=actual_receipt)
  THEN RAISE EXCEPTION 'CSV creation eligibility absent on replay' USING ERRCODE='42501'; END IF;
 END IF;
 INSERT INTO twuanis_canonical_private.csv_initial_publication(creation_receipt,listing_id)
 VALUES(actual_receipt,(result->>'listing_id')::uuid) ON CONFLICT(creation_receipt) DO NOTHING;
 RETURN result||jsonb_build_object('csv_creation_receipt',actual_receipt::text);
END $function$
"}, {"acl": "{postgres=X/postgres,service_role=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog"], "signature": "public.initially_publish_csv_listing(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.initially_publish_csv_listing(p_creation_receipt uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE eligibility twuanis_canonical_private.csv_initial_publication%ROWTYPE; l public.listings%ROWTYPE; r public.canonical_operation_receipts%ROWTYPE; result jsonb; completed boolean;
BEGIN
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 SELECT * INTO eligibility FROM twuanis_canonical_private.csv_initial_publication WHERE creation_receipt=p_creation_receipt FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CSV creation eligibility required' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.canonical_operation_receipts WHERE id=eligibility.creation_receipt;
 IF NOT FOUND OR r.listing_id IS DISTINCT FROM eligibility.listing_id OR r.operation_type<>'create_trusted'
 OR r.authority_kind<>'trusted' OR r.authority_identity<>'service_role' OR r.result_revision<>1
 OR NOT EXISTS(SELECT 1 FROM public.listing_lifecycle_events WHERE operation_id=r.id AND listing_id=r.listing_id AND event_type='create' AND resulting_state='draft')
 THEN RAISE EXCEPTION 'invalid CSV creation receipt' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT l FROM public.listings WHERE id=eligibility.listing_id;
 IF l.owner_id IS NOT NULL OR l.publisher_account_id IS NOT NULL OR l.canonical_domain_version IS DISTINCT FROM 1
 OR l.listing_origin IS DISTINCT FROM 'imported' OR l.source_name IS NULL OR l.source_listing_id IS NULL
 THEN RAISE EXCEPTION 'ownerless canonical CSV import required' USING ERRCODE='42501'; END IF;
 SELECT EXISTS(SELECT 1 FROM public.canonical_operation_receipts WHERE authority_kind='trusted' AND authority_identity='service_role'
 AND operation_type='domain_mutation' AND request_id=eligibility.publication_request AND listing_id=l.id AND outcome='succeeded') INTO completed;
 IF NOT completed AND (l.listing_status IS DISTINCT FROM 'draft' OR EXISTS(
  SELECT 1 FROM public.listing_lifecycle_events WHERE listing_id=l.id AND event_type='publish'))
 THEN RAISE EXCEPTION 'unpublished canonical draft required' USING ERRCODE='55000'; END IF;
 IF NOT completed THEN
  UPDATE twuanis_canonical_private.csv_initial_publication SET publication_expected=l.canonical_revision
  WHERE creation_receipt=p_creation_receipt;
  eligibility.publication_expected:=l.canonical_revision;
 END IF;
 -- Persisted expected revision and fixed operation identity survive successful replay.
 -- A failed command rolls the expectation back with its transaction.
 result:=twuanis_canonical_private.s3_command(l.id,eligibility.publication_expected,'trusted','service_role',eligibility.publication_request,
 '{"lifecycle":{"event":"publish","duration_seconds":"7776000"}}'::jsonb,NULL);
 RETURN result||jsonb_build_object('listing_id',l.id::text);
END $function$
"}, {"acl": "{postgres=X/postgres}", "owner": "postgres", "present": true, "security": "INVOKER", "settings": ["search_path=pg_catalog"], "signature": "twuanis_canonical_private.guard_publication_entitlement()", "definition": "CREATE OR REPLACE FUNCTION twuanis_canonical_private.guard_publication_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.publication_duration_seconds IS NOT NULL AND current_user<>'postgres' THEN
   RAISE EXCEPTION 'database administration required for publication entitlement' USING ERRCODE='42501'; END IF;
 ELSE
  IF (NEW.package_id,NEW.publication_duration_seconds) IS DISTINCT FROM (OLD.package_id,OLD.publication_duration_seconds)
   AND current_user<>'postgres' THEN RAISE EXCEPTION 'database administration required for publication entitlement' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN NEW;
END $function$
"}, {"acl": "{postgres=X/postgres,authenticated=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog"], "signature": "public.publish_customer_canonical_listing(uuid,bigint,uuid,text)", "definition": "CREATE OR REPLACE FUNCTION public.publish_customer_canonical_listing(p_listing uuid, p_expected bigint, p_request uuid, p_event text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid();publisher uuid;governing record;c twuanis_canonical_private.customer_publication_commands%ROWTYPE;seconds bigint;result jsonb;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated customer required' USING ERRCODE='42501'; END IF;
 IF p_request IS NULL OR p_listing IS NULL OR p_expected IS NULL OR p_expected<0 OR p_event IS NULL OR p_event NOT IN ('publish','renew')
 THEN RAISE EXCEPTION 'explicit bounded publication command required' USING ERRCODE='22023'; END IF;
 publisher:=twuanis_canonical_private.resolve_publisher(actor);
 IF NOT EXISTS(SELECT 1 FROM public.listings WHERE id=p_listing AND owner_id=actor AND publisher_account_id=publisher AND canonical_domain_version=1)
 THEN RAISE EXCEPTION 'owned canonical listing required' USING ERRCODE='42501'; END IF;
 -- Same operation lock as S3, after the established policy/publisher lock order.
 PERFORM pg_advisory_xact_lock(3104,hashtext(jsonb_build_array('owner',actor::text,'domain_mutation',p_request)::text));
 SELECT * INTO c FROM twuanis_canonical_private.customer_publication_commands WHERE owner_id=actor AND request_id=p_request;
 IF FOUND THEN
  IF (c.listing_id,c.expected_revision,c.event) IS DISTINCT FROM (p_listing,p_expected,p_event)
  THEN RAISE EXCEPTION 'publication retry payload conflict' USING ERRCODE='22023'; END IF;
  seconds:=c.duration_seconds;
 ELSE
  SELECT * INTO STRICT governing FROM twuanis_canonical_private.publisher_allowance(publisher,actor);
  SELECT publication_duration_seconds INTO seconds FROM public.package_limits WHERE package_id=governing.package_id;
  IF seconds IS NULL OR seconds<=0 OR seconds>315576000 THEN RAISE EXCEPTION 'valid package publication entitlement required' USING ERRCODE='55000'; END IF;
  INSERT INTO twuanis_canonical_private.customer_publication_commands(owner_id,request_id,listing_id,expected_revision,event,duration_seconds,package_id)
  VALUES(actor,p_request,p_listing,p_expected,p_event,seconds,governing.package_id);
 END IF;
 result:=twuanis_canonical_private.s3_command(p_listing,p_expected,'owner',actor::text,p_request,
 jsonb_build_object('lifecycle',jsonb_build_object('event',p_event,'duration_seconds',seconds::text)),NULL);
 RETURN result||jsonb_build_object('listing_id',p_listing::text);
END $function$
"}, {"acl": "{postgres=X/postgres,authenticated=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "public.prepare_customer_duplicate(uuid,uuid)", "definition": "CREATE OR REPLACE FUNCTION public.prepare_customer_duplicate(p_source uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); l public.listings%ROWTYPE; cmd twuanis_canonical_private.duplicate_commands%ROWTYPE;
 input jsonb; geo jsonb; sem jsonb; facts jsonb:='{}'; measurements jsonb:='{}'; f record; v jsonb;
 result jsonb; media jsonb:='[]'; paths jsonb; item text; i integer:=0; creation_request uuid:=gen_random_uuid(); classified jsonb:='{}'; rules uuid[]; dim text; domain_group text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated owner required' USING ERRCODE='42501'; END IF;
 IF p_source IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'source and request required' USING ERRCODE='22023'; END IF;
 -- Same order as canonical creation: policy/publisher before operation and listing locks.
 PERFORM twuanis_canonical_private.ensure_publisher_account(actor);
 PERFORM pg_advisory_xact_lock(3113,hashtext(jsonb_build_array(actor,p_request)::text));
 SELECT * INTO cmd FROM twuanis_canonical_private.duplicate_commands WHERE owner_id=actor AND request_id=p_request;
 IF FOUND THEN
  IF cmd.source_id<>p_source THEN RAISE EXCEPTION 'duplicate request conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('listing_id',cmd.listing_id::text,'media',cmd.media,'completed',cmd.completed);
 END IF;
 SELECT * INTO l FROM public.listings WHERE id=p_source AND owner_id=actor FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'owned source required' USING ERRCODE='42501'; END IF;
 IF l.canonical_domain_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'source requires canonical evidence adapter' USING ERRCODE='55000'; END IF;
 SELECT jsonb_object_agg(t.term_type,t.official_code) INTO geo FROM public.listing_membership_origins m JOIN public.ontology_terms t ON t.id=m.ontology_term_id WHERE m.listing_id=l.id AND m.origin_domain='geography' AND t.term_type IN ('province','canton','district');
 SELECT jsonb_object_agg(dimension,ids) INTO sem FROM (SELECT dimension,jsonb_agg(ontology_term_id::text ORDER BY ontology_term_id) ids FROM public.listing_semantic_selections WHERE listing_id=l.id GROUP BY dimension)s;
 FOR f IN SELECT * FROM public.listing_fact_evidence WHERE listing_id=l.id LOOP
  v:=CASE f.kind WHEN 'exact' THEN jsonb_build_object('kind','exact','value',f.exact_value::text)
   WHEN 'category' THEN jsonb_build_object('kind','category','term',f.category_term_id::text)
   ELSE jsonb_build_object('kind','range','lower',f.range_lower::text,'upper',f.range_upper::text,'lower_inclusive',f.lower_inclusive,'upper_inclusive',f.upper_inclusive) END;
  facts:=facts||jsonb_build_object(f.dimension,v);
 END LOOP;
 IF l.property_area IS NOT NULL THEN measurements:=measurements||jsonb_build_object('property_area',jsonb_build_object('value',l.property_area::text)); END IF;
 IF l.construction_area IS NOT NULL THEN measurements:=measurements||jsonb_build_object('construction_area',jsonb_build_object('value',l.construction_area::text)); END IF;
 input:=jsonb_build_object('transaction',l.transaction_type,'geography',geo,'semantics',sem,'facts',facts,'measurements',measurements,
  'content',jsonb_strip_nulls(jsonb_build_object('title',left(coalesce(nullif(l.title,''),'Listing')||' — Copy',512),'description',l.description,'whatsapp',l.whatsapp)));
 IF (CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END) IS NOT NULL THEN
  input:=input||jsonb_build_object('money',jsonb_build_object('amount',(CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END)::text,'currency',l.currency));
 END IF;
 IF l.listing_origin IS DISTINCT FROM 'customer' OR l.listing_source_type IS DISTINCT FROM 'customer' OR l.source_name IS NOT NULL OR l.source_listing_id IS NOT NULL THEN RAISE EXCEPTION 'customer source provenance required' USING ERRCODE='42501'; END IF;
 -- Preserve only customer-owned source objects. Never accept URL/shared paths.
 IF l.images IS NULL OR btrim(l.images::text)='' THEN paths:='[]';
 ELSE BEGIN paths:=l.images::text::jsonb; EXCEPTION WHEN invalid_text_representation THEN paths:=to_jsonb(string_to_array(l.images::text,'|')); END; END IF;
 IF jsonb_typeof(paths)='string' THEN paths:=jsonb_build_array(paths); END IF;
 IF jsonb_typeof(paths)<>'array' OR jsonb_array_length(paths)>25 THEN RAISE EXCEPTION 'invalid source media' USING ERRCODE='22023'; END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(paths) LOOP
  item:=v#>>'{}';
  IF jsonb_typeof(v)<>'string' OR item NOT LIKE (actor::text||'/'||l.id::text||'/%') OR item ~ '(^|/)[.][.]?(/|$)' OR item ~ '[\\]' OR item ~ '[?#]' OR item !~ ('^'||actor::text||'/'||l.id::text||'/[a-zA-Z0-9_-]+[.]jpg$') OR length(item)>1024 THEN RAISE EXCEPTION 'source media ownership invalid' USING ERRCODE='42501'; END IF;
 END LOOP;
 -- Rule policy is read from the source, never supplied by the caller.
 FOR f IN SELECT origin_domain,array_agg(DISTINCT r.rule_set_id) sets
 FROM public.listing_membership_origins m JOIN public.listing_classification_rules r ON r.id=m.classification_rule_id
 WHERE m.listing_id=l.id AND m.classification_rule_id IS NOT NULL GROUP BY origin_domain LOOP
  dim:=f.origin_domain;rules:=f.sets;
  IF cardinality(rules)<>1 THEN RAISE EXCEPTION 'ambiguous recorded classification' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.classification_seals z JOIN public.listing_classification_rule_sets r ON r.id=z.rule_set_id WHERE r.id=rules[1] AND r.domain=dim) THEN RAISE EXCEPTION 'recorded sealed typed rule required' USING ERRCODE='55000'; END IF;
  domain_group:=CASE WHEN dim IN ('property_area','construction_area') THEN 'measurements' ELSE 'facts' END;
  v:=input->domain_group->dim;
  IF v IS NULL OR (domain_group='facts' AND v->>'kind' IS DISTINCT FROM 'exact') THEN RAISE EXCEPTION 'recorded rule without exact evidence' USING ERRCODE='55000'; END IF;
  IF domain_group='facts' THEN v:=v||'{"source":"owner"}'::jsonb; END IF;
  classified:=classified||jsonb_build_object(domain_group,coalesce(classified->domain_group,'{}')||jsonb_build_object(dim,v||jsonb_build_object('rule_set',rules[1]::text)));
 END LOOP;
 -- Private request avoids colliding with ordinary customer creation requests.
 result:=twuanis_canonical_private.s4_create_core(actor,creation_request,input,NULL);
 IF classified<>'{}'::jsonb THEN
  PERFORM twuanis_canonical_private.s3_command((result->>'listing_id')::uuid,1,'owner',actor::text,gen_random_uuid(),classified,NULL);
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements_text(paths) LOOP
  i:=i+1;
  media:=media||jsonb_build_array(jsonb_build_object('source',item,'destination',actor::text||'/'||(result->>'listing_id')||'/duplicate-'||gen_random_uuid()::text||'.jpg'));
 END LOOP;
 INSERT INTO twuanis_canonical_private.duplicate_commands(owner_id,request_id,source_id,listing_id,creation_receipt,media)
 VALUES(actor,p_request,p_source,(result->>'listing_id')::uuid,(result->>'receipt_id')::uuid,media);
 RETURN jsonb_build_object('listing_id',result->>'listing_id','media',media,'completed',false);
END $function$
"}, {"acl": "{postgres=X/postgres,service_role=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "public.attach_customer_duplicate_media(uuid)", "definition": "CREATE OR REPLACE FUNCTION public.attach_customer_duplicate_media(p_listing uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE cmd twuanis_canonical_private.duplicate_commands%ROWTYPE; l public.listings%ROWTYPE; paths jsonb;
BEGIN
 SELECT * INTO l FROM public.listings WHERE id=p_listing FOR UPDATE;
 SELECT * INTO cmd FROM twuanis_canonical_private.duplicate_commands WHERE listing_id=p_listing FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'duplicate manifest required' USING ERRCODE='55000'; END IF;
 IF cmd.completed THEN RETURN jsonb_build_object('listing_id',p_listing::text,'completed',true); END IF;
 IF l.owner_id IS DISTINCT FROM cmd.owner_id OR l.canonical_domain_version IS DISTINCT FROM 1 OR l.listing_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'unchanged owned canonical draft required' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(value->>'destination' ORDER BY ordinal),'[]') INTO paths FROM jsonb_array_elements(cmd.media) WITH ORDINALITY m(value,ordinal);
 IF l.images IS NOT NULL AND btrim(l.images::text) NOT IN ('','[]','null') AND l.images::text IS DISTINCT FROM paths::text THEN RAISE EXCEPTION 'draft media changed; no overwrite' USING ERRCODE='40001'; END IF;
 UPDATE public.listings SET images=paths::text WHERE id=p_listing;
 UPDATE twuanis_canonical_private.duplicate_commands SET completed=true WHERE listing_id=p_listing;
 RETURN jsonb_build_object('listing_id',p_listing::text,'completed',true);
END $function$
