"}, {"acl": "{postgres=X/postgres,authenticated=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "public.edit_customer_canonical_listing(uuid,bigint,uuid,jsonb,jsonb)", "definition": "CREATE OR REPLACE FUNCTION public.edit_customer_canonical_listing(p_listing uuid, p_expected bigint, p_request uuid, p_domains jsonb, p_content jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); previous twuanis_canonical_private.customer_content_edits%ROWTYPE; item record; result jsonb;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated customer required' USING ERRCODE='42501'; END IF;
 PERFORM twuanis_canonical_private.s3_keys(p_content,ARRAY['title','description','whatsapp']);
 FOR item IN SELECT key,value FROM jsonb_each(p_content) LOOP
  IF jsonb_typeof(item.value)<>'string' OR length(item.value#>>'{}')>(CASE item.key WHEN 'title' THEN 512 WHEN 'description' THEN 16000 ELSE 256 END) THEN RAISE EXCEPTION 'bounded content required' USING ERRCODE='22023'; END IF;
 END LOOP;
 PERFORM twuanis_canonical_private.ensure_publisher_account(actor);
 PERFORM pg_advisory_xact_lock(3104,hashtext(jsonb_build_array('owner',actor::text,'domain_mutation',p_request)::text));
 SELECT * INTO previous FROM twuanis_canonical_private.customer_content_edits WHERE owner_id=actor AND request_id=p_request;
 IF FOUND THEN
  IF previous.listing_id IS DISTINCT FROM p_listing OR previous.expected_revision IS DISTINCT FROM p_expected OR previous.content IS DISTINCT FROM p_content THEN RAISE EXCEPTION 'content idempotency conflict' USING ERRCODE='22023'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM public.canonical_operation_receipts WHERE authority_kind='owner' AND authority_identity=actor::text AND operation_type='domain_mutation' AND request_id=p_request) THEN RAISE EXCEPTION 'request already belongs to a different operation' USING ERRCODE='22023'; END IF;
  INSERT INTO twuanis_canonical_private.customer_content_edits(owner_id,request_id,listing_id,expected_revision,content) VALUES(actor,p_request,p_listing,p_expected,p_content);
 END IF;
 result:=public.mutate_customer_canonical_listing(p_listing,p_expected,p_request,p_domains);
 IF coalesce(previous.completed,false) THEN RETURN result; END IF;
 UPDATE public.listings SET
 title=CASE WHEN p_content?'title' THEN p_content->>'title' ELSE title END,
 description=CASE WHEN p_content?'description' THEN p_content->>'description' ELSE description END,
 whatsapp=CASE WHEN p_content?'whatsapp' THEN p_content->>'whatsapp' ELSE whatsapp END
 WHERE id=p_listing AND owner_id=actor AND canonical_domain_version=1;
 IF NOT FOUND THEN RAISE EXCEPTION 'owned canonical listing required' USING ERRCODE='42501'; END IF;
 UPDATE twuanis_canonical_private.customer_content_edits SET completed=true WHERE owner_id=actor AND request_id=p_request;
 RETURN result;
END $function$
"}, {"acl": "{postgres=X/postgres,service_role=X/postgres}", "owner": "postgres", "present": true, "security": "DEFINER", "settings": ["search_path=pg_catalog, pg_temp"], "signature": "public.prepare_token_canonical_listing(text,uuid,jsonb,jsonb)", "definition": "CREATE OR REPLACE FUNCTION public.prepare_token_canonical_listing(p_token text, p_owner uuid, p_snapshot jsonb, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE t public.listing_publish_tokens%ROWTYPE;c twuanis_canonical_private.token_creation_commands%ROWTYPE;
 result jsonb;media jsonb:='[]';paths jsonb;v jsonb;item text;
BEGIN
 IF p_owner IS NULL OR p_token IS NULL OR p_token !~ '^[0-9a-f-]{36}$' THEN RAISE EXCEPTION 'explicit token/customer required' USING ERRCODE='22023';END IF;
 PERFORM twuanis_canonical_private.ensure_publisher_account(p_owner);
 SELECT * INTO t FROM public.listing_publish_tokens WHERE token=p_token FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'token not found' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM twuanis_canonical_private.token_creation_commands WHERE token=p_token;
 IF FOUND THEN
  IF c.owner_id<>p_owner THEN RAISE EXCEPTION 'token owner conflict' USING ERRCODE='42501';END IF;
  RETURN jsonb_build_object('listing_id',c.listing_id::text,'media',c.media,'completed',c.media_completed,'publication',c.publication_result,'transaction',(SELECT transaction_type FROM public.listings WHERE id=c.listing_id));
 END IF;
 IF t.published_at IS NOT NULL OR t.published_listing_id IS NOT NULL OR t.verified IS TRUE THEN RAISE EXCEPTION 'previously completed token is not new creation' USING ERRCODE='55000';END IF;
 IF p_snapshot IS NULL OR t.listing_data::jsonb IS DISTINCT FROM p_snapshot THEN RAISE EXCEPTION 'token input changed' USING ERRCODE='40001';END IF;
 paths:=coalesce(t.listing_data->'temporary_images','[]');
 IF jsonb_typeof(paths)<>'array' OR jsonb_array_length(paths)>25 OR coalesce(t.listing_data->'images','[]') IS DISTINCT FROM paths THEN RAISE EXCEPTION 'explicit managed temporary media required' USING ERRCODE='22023';END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(paths) LOOP
  item:=v#>>'{}';
  IF jsonb_typeof(v)<>'string' OR item !~ ('^temporary/'||p_token||'/[a-zA-Z0-9_-]+[.]jpg$') THEN RAISE EXCEPTION 'token media provenance invalid' USING ERRCODE='42501';END IF;
 END LOOP;
 IF (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements(paths)) THEN RAISE EXCEPTION 'duplicate media source' USING ERRCODE='22023';END IF;
 result:=twuanis_canonical_private.s4_create_core(p_owner,gen_random_uuid(),p_input,NULL);
 FOR item IN SELECT value FROM jsonb_array_elements_text(paths) LOOP
  media:=media||jsonb_build_array(jsonb_build_object('source',item,'destination',p_owner::text||'/'||(result->>'listing_id')||'/token-'||gen_random_uuid()::text||'.jpg'));
 END LOOP;
 INSERT INTO twuanis_canonical_private.token_creation_commands(token,owner_id,listing_id,media) VALUES(p_token,p_owner,(result->>'listing_id')::uuid,media);
 UPDATE public.listing_publish_tokens SET claimed_at=clock_timestamp() WHERE id=t.id;
 RETURN jsonb_build_object('listing_id',result->>'listing_id','media',media,'completed',false,'publication',NULL,'transaction',p_input->>'transaction');
END $function$
